    assert sorted_intersection([2, 2, 2, 7], [2, 2, 7, 7]) == [2, 7]


def test_output_ascending_regardless_of_input_order():
    assert sorted_intersection([9, 4, 6, 1], [6, 1, 9, 4]) == [1, 4, 6, 9]


def test_no_overlap_returns_empty():
    assert sorted_intersection([1, 2], [3, 4]) == []


def test_empty_left_returns_empty():
    assert sorted_intersection([], [1, 2, 3]) == []


def test_empty_right_returns_empty():
    assert sorted_intersection([1, 2, 3], []) == []


def test_both_empty_returns_empty():
    assert sorted_intersection([], []) == []


def test_negative_integers_supported():
    assert sorted_intersection([-5, 0, 3, -1], [-1, -5, 8]) == [-5, -1]


def test_identical_lists():
    assert sorted_intersection([4, 2, 2], [2, 4]) == [2, 4]


def test_inputs_not_mutated():
    left = [3, 1, 2]
    right = [2, 3, 3]
    sorted_intersection(left, right)
    assert left == [3, 1, 2]
    assert right == [2, 3, 3]


